import json
from pathlib import Path
r=Path(__file__).parent
def read(path):return (r/'exemplo'/path).read_text()
def loc(file,folder,action,responsibility):return dict(file=file,folder=folder,action=action,responsibility=responsibility)
def part(title,text,code,location,language='python',explain=''):
 return dict(title=title,text=text,code=code,location=location,language=language,explain=explain)
T=lambda folder,action:loc('Não é arquivo: terminal',folder,action,'Executa comandos do sistema e do Django no diretório informado.')
def F(path,action,resp):return loc('exemplo/'+path,'exemplo/'+str(Path(path).parent)+'/',action,resp)
g=[]
def step(title,scenario,prereq,parts,result):g.append(dict(title=title,scenario=scenario,prereq=prereq,parts=parts,result=result))
